function formSelector() {
  const selected = document.getElementById("templateSelect").value;
  const item = Office.context.mailbox.item;
  
  if (!item) {
    return;
  }

  const isCompose = item?.body?.setAsync !== undefined;

  hideElements(fields[selected].remove);
  showElements(fields[selected].keep);

  if (!isCompose) {
    hideElements([
      document.getElementById("divToEmail"),
      document.getElementById("divToCC"),
    ]);
  }
  // setStatus(selected);
}

async function onStart() {
  // try {
  //   const client = await getGraphClient();
  //   const user = await client.api("/me").get();
  //   setStatus("department" + user.department + "user" + user);
  // } catch (error) {
  //   setStatus(error.message);
  // }
  const btn = document.getElementById("generateBtn");
  const item = Office.context.mailbox.item;
  const selected = document.getElementById("templateSelect");

  if (!item) {
    return;
  }

  const isCompose = item?.body?.setAsync !== undefined;

  if (!isCompose) {
    // Read Mode - Hide fields not relevant to read mode
    hideElements([
      document.getElementById("divToEmail"),
      document.getElementById("divToCC"),
    ]);
  }

  formSelector();

  if (!btn) return;
  if (!selected) return;

    // Attach listener
  if (!btn.hasAttribute("data-listener")){
    btn.setAttribute("data-listener", "true")
    btn.addEventListener("click", generateEmail);
  }

  if (!selected.hasAttribute("data-listener")){
    selected.setAttribute("data-listener", "true")
    selected.addEventListener("change", formSelector);
  }
}

function hideElements(elements) {
  elements.forEach(element => {
    element.style.display = "none";
  });
}

function showElements(elements) {
  elements.forEach(element => {
    element.style.display = "block";
  });
}

