function fillTemplate(template, data){

  return template.replace(/{(.*?)}/g, (match,key)=>{
  return data[key] || "";
  });
}

function setStatus(msg, isError = false) {
  const el = document.getElementById("status");
  el.textContent = msg;
  el.style.color = isError ? "crimson" : "green";
}

function escapeHtml(str) {
  return (str || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function emailWrapper(content, data, key) {
  const ignoreSurvey = []; //Use in line "key != "acknowledgement" when all 

  return `
    <p>Dear ${escapeHtml(data.clientName) || "Sir/Madam"},</p>
    <br>
    ${fillTemplate(content, data)}
    <br>
    ${data.ticketNo ? `<p>Ticket Number: <b>${data.ticketNo}</b></p>` : ""}
  `;
}

function buildTemplate(templateKey, data) {
  const tpl = templates[templateKey];

  if (!tpl) {
    throw new Error("Template not found: " + templateKey);
  }

  return {
    subject: tpl.subject,
    bodyHtml: emailWrapper(tpl.body, data, templateKey)
  };
}

function generateEmail() {
  if (generating) return;
  generating = true;

  try {
    const item = Office.context.mailbox.item;

    // Ensure we are in compose mode
    if (!item) {
      setStatus("Open a new email (compose) then try again.", true);
      return;
    }
    
    const templateKey = document.getElementById("templateSelect").value;
    const toEmail = document.getElementById("toEmail").value.trim();
    const toCC = document.getElementById("toCC").value.trim();
    const clientName = document.getElementById("clientName").value.trim();
    const ticketNo = document.getElementById("ticketNo").value.trim();
    const email = document.getElementById("email").value.trim();
    const password = document.getElementById("password").value.trim();

    if (ticketNo !== "") {
      if (ticketNo !== "" && isNaN(ticketNo)) {
        setStatus("Please enter a number as the Ticket #");
        return;
      }
    }

    const data = {
      toEmail,
      clientName,
      ticketNo,
      email,
      password
    };

    const tpl = buildTemplate(templateKey, data);

    const isCompose = item?.body?.setAsync !== undefined;

    if (!isCompose) {
      // Read Mode
      Office.context.mailbox.item.displayReplyAllForm({
        htmlBody: tpl.bodyHtml
      });

      setStatus("Reply email generated. Review and send.");
      return;
    } else {
      // Compose Mode
      item.subject.setAsync(tpl.subject);

      item.body.prependAsync(
        tpl.bodyHtml,
        { coercionType: Office.CoercionType.Html }
      );

      if (toEmail) {
        item.to.setAsync([toEmail]);
      } else {
        item.to.setAsync([]);
      }

      if (toCC) {
        item.cc.setAsync([toCC]);
      } else {
        item.cc.setAsync([]);
      }

      setStatus("New email generated. Review and send.");
      return;
    }
  } catch (e) {
    setStatus("Error: " + (e?.stack || e), true);
  } finally {
    generating = false;
  }
}